insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('google-adk','google-adk','Google Agent Development Kit (ADK)','framework','מסגרת קוד פתוח של Google לבניית סוכנים, כלים ותהליכי עבודה, עם סביבת פיתוח, הרצה והערכה. מתאימה ללימוד ההפרדה בין לוגיקת הסוכן, מצב השיחה ותשתית הפריסה.','published','verified','2026-11-02',1,'מקורות רשמיים נבדקו ב־2026-11-02; דוגמאות, תרגילים והשוואות מסומנים כפדגוגיים ולא הורצו. אין אימות מעבדתי לכל API.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User request 2026-11-02: add ADK, Mastra, smolagents, Agno and Legacy AutoGen; docs/DECISIONS.md D-029');
insert into academy.entry_categories (entry_id,category_id,position) values ('google-adk','02',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('google-adk','היכרות עם REST/JSON, אימות קלט, לולאת tool calling והפרדת לוגיקה עסקית מהמודל.','דוגמה לימודית מוצעת, שלא הורצה כאן: React שולח בקשת ציוד ל־ASP.NET Core. שירות ADK מסווג את הבקשה וקורא לכלי בירור מלאי בקריאה בלבד דרך REST. שרת .NET מאמת את הנתונים ומציג הצעת הזמנה לאישור אדם לפני כל כתיבה ל־SQL.','תכננו אותו תרחיש עם סוכן יחיד ועם Workflow רציף. הגדירו בקשת JSON, תשובה צפויה, מגבלת זמן ומקרה כשל של שירות המלאי. השוו את גבולות האחריות למימוש ב־LangGraph או ב־Microsoft Agent Framework.','התיעוד הרשמי מציג Python, TypeScript, Go, Java ו־Kotlin. זמינות תכונות תלויה בשפה ובגרסה; אין להסיק שוויון בין המימושים. C#/.NET: לא נמצא SDK רשמי ברשימת השפות שנבדקה. אפשר לתכנן שירות ADK נפרד ולקרוא לו מ־ASP.NET Core באמצעות HTTP; זו אינטגרציה בין שירותים ולא SDK מקומי ל־C#.','LangGraph לשליטה מפורשת בזרימה ובמצב; OpenAI Agents SDK ללולאת סוכן ממוקדת; Microsoft Agent Framework למימוש C#/.NET. הבחירה תלויה בדרישות ולא במספר Stars.');
insert into academy.entry_sections (entry_id,position,title,body) values ('google-adk',0,'איזו בעיה הוא פותר?','ADK מחבר מודל, כלים והקשר הרצה כדי לבנות עוזרי שירות ותהליכי איסוף מידע. הוא מציע גם תזמור רציף, מקבילי ולולאות; אין צורך להתחיל מצוות סוכנים אם סוכן יחיד פותר את הבעיה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('google-adk',1,'איך בנויה ההרצה?','סוכן מקבל בקשה, בוחר כלים ומחזיר אירועים ותוצאה דרך סביבת ההרצה. Session שומר הקשר, וכלי הוא גבול מפורש לפעולה עסקית. בדומה ל־ASP.NET Core, מומלץ להפריד בין תזמור הבקשה לשירות הדומיין שמאמת הרשאות וקלט.');
insert into academy.entry_sections (entry_id,position,title,body) values ('google-adk',2,'שימושים מרכזיים','עוזר ידע ארגוני, סיווג בקשות ותהליכי עבודה עם כלים. סביבת הפיתוח המקומית וההערכות מאפשרות לבדוק מסלולים ותוצאות; יכולת אינטגרציה עם מודלים אחרים אינה מבטיחה שכל תכונה אחידה בכל ספק.');
insert into academy.entry_sections (entry_id,position,title,body) values ('google-adk',3,'מתי לבחור ובמה להשוות?','השוואה פדגוגית: מול LangGraph בדקו כמה שליטה מפורשת בגרף ובמצב נחוצה; מול OpenAI Agents SDK בדקו מורכבות לולאת הכלים; מול Microsoft Agent Framework בדקו שפה, תחזוקה ואינטגרציה עם קוד .NET. אין כאן טענה לעדיפות ביצועים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('google-adk',4,'גבולות ובטיחות','מודל אינו מחליף אימות הרשאות. הגבילו כלים, שמרו סודות בשרת ובדקו עלות וזמן הרצה. פריסה ל־Google Cloud היא אפשרות ולא דרישה להקמת תרגיל מקומי; הפיצול לשירות נוסף הוא החלטת ארכיטקטורה.');
insert into academy.entry_sources (entry_id,position,source_url,title,checked_at,supports) values ('google-adk',0,'https://adk.dev/','Google Agent Development Kit (ADK) — תיעוד רשמי','2026-11-02','תפקיד, מבנה ותמיכת שפות; טענות על היעדר SDK מוגבלות למקורות שנבדקו.');
