insert into academy.entry_sources (entry_id,position,source_url,title,checked_at,supports) values ('google-adk',2,'https://developers.googleblog.com/agent-development-kit-easy-to-build-multi-agent-applications/','Google Developers — הכרזת ADK','2026-11-02','שנת ההכרזה הציבורית על ADK ב־Google Cloud Next 2025. אינה שנת הקמת Google או מועד יצירת המאגר; לא נקבע יום כשדי בשנה המאומתת.');
