insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('google-adk','מסגרת של Google לבניית סוכנים וכלים, תהליכי עבודה והרצה הניתנת לבדיקה.','התיעוד הרשמי מציג Python, TypeScript, Go, Java ו־Kotlin. זמינות תכונות תלויה בשפה ובגרסה; אין להסיק שוויון בין המימושים. C#/.NET: לא נמצא SDK רשמי ברשימת השפות שנבדקה. אפשר לתכנן שירות ADK נפרד ולקרוא לו מ־ASP.NET Core באמצעות HTTP; זו אינטגרציה בין שירותים ולא SDK מקומי ל־C#.','verified','Stars ופעילות של מאגר Python בלבד; אינם סכום מאגרי ADK בשפות השונות.','2026-11-02T18:53:28.133Z');
