insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('mastra','mastra','Mastra','framework','מסגרת TypeScript לבניית יישומי AI וסוכנים, עם כלים, תהליכי עבודה, זיכרון, הערכה ותצפיתיות. מיועדת לצוותי מוצר שרוצים לכתוב את שכבת הסוכנים באקוסיסטם Node.js.','published','verified','2026-11-02',1,'מקורות רשמיים נבדקו ב־2026-11-02; דוגמאות, תרגילים והשוואות מסומנים כפדגוגיים ולא הורצו. אין אימות מעבדתי לכל API.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User request 2026-11-02: add ADK, Mastra, smolagents, Agno and Legacy AutoGen; docs/DECISIONS.md D-029');
insert into academy.entry_categories (entry_id,category_id,position) values ('mastra','02',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('mastra','היכרות עם REST/JSON, אימות קלט, לולאת tool calling והפרדת לוגיקה עסקית מהמודל.','דוגמה לימודית מוצעת, שלא הורצה כאן: מסך React שולח פנייה לשירות Mastra. Workflow מאחזר סטטוס הזמנה מ־API של .NET, מבקש מהמודל ניסוח תשובה ומחזיר טיוטה לבדיקה. זיכוי כספי אינו מבוצע מתוך הטיוטה אלא לאחר אישור ופקודת שרת נפרדת.','הגדירו שלושה צעדים: שליפת הזמנה, יצירת טיוטה ואישור. תכננו מה נשמר כשאחד השלבים נכשל, ובדקו בקשה ללא הרשאה. השוו למימוש המקביל ב־OpenAI Agents SDK.','TypeScript היא שפת המסגרת הרשמית באקוסיסטם JavaScript/Node.js. אין כאן SDK Python או C#/.NET מקומי מאומת. אפשר לחשוף שירות Mastra מאומת ולצרוך את ה־API מ־C# או Python; הלקוח אינו הופך את שפת הצריכה לשפת המסגרת.','LangGraph ו־OpenAI Agents SDK הן חלופות קיימות לבחינת תזמור סוכן ב־TypeScript. Microsoft Agent Framework מתאים יותר לבחינת מימוש מקומי ב־C#; אין להסיק עדיפות מנתוני GitHub בלבד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mastra',0,'איזו בעיה היא פותרת?','Mastra מאגדת בניית סוכן, כלים ו־Workflows ב־TypeScript. שימושים מרכזיים הם עוזרי מוצר, עיבוד בקשות ותהליכים שמשלבים קריאות מודל עם צעדים עסקיים מפורשים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mastra',1,'איך בנויה ההרצה?','מגדירים Agent וכלים עם סכמות קלט, ומרכיבים צעדים ב־Workflow לפי הצורך. זיכרון, אחסון ו־traces הם רכיבים בעלי אחריות נפרדת. כלי שקורא REST דומה למתאם שירות ב־C#; חוקי הדומיין ממשיכים להיאכף בשרת המוסמך.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mastra',2,'שימושים מרכזיים','עוזר תמיכה בתוך יישום React, יצירת טיוטת תשובה עם מידע ארגוני ותהליך שצריך לעצור לאישור. היכולת לצפות בהרצה ולהעריך פלטים אינה ערובה לנכונות; יש להכין מקרי בדיקה עסקיים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mastra',3,'מתי לבחור ובמה להשוות?','השוואה פדגוגית: Mastra מתאימה לבחינת חבילה משולבת לצוות TypeScript. השוו ל־LangGraph כשחשובה שליטה בגרף, ול־OpenAI Agents SDK כשרוצים לולאת סוכן ממוקדת. מול Microsoft Agent Framework שקלו האם נכון להשאיר את השרת ב־C#.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mastra',4,'גבולות ובטיחות','אל תעבירו סודות לדפדפן React ואל תתנו לכלי גישה חופשית למסד. יש לאמת משתמשים גם כשהסוכן חשוף כ־API. יכולות תלויות בגרסה, ולכן דוגמאות ישנות דורשות התאמה לתיעוד הנוכחי.');
