insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('smolagents','smolagents','Hugging Face smolagents','framework','ספריית Python לסוכנים שמבצעים פעולות באמצעות קוד או קריאות כלים. מתאימה להבנת לולאת סוכן מצומצמת ולעבודה עם מודלים שונים, תוך תשומת לב מיוחדת לבידוד הרצת קוד.','published','verified','2026-11-02',1,'מקורות רשמיים נבדקו ב־2026-11-02; דוגמאות, תרגילים והשוואות מסומנים כפדגוגיים ולא הורצו. אין אימות מעבדתי לכל API.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User request 2026-11-02: add ADK, Mastra, smolagents, Agno and Legacy AutoGen; docs/DECISIONS.md D-029');
insert into academy.entry_categories (entry_id,category_id,position) values ('smolagents','02',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('smolagents','היכרות עם REST/JSON, אימות קלט, לולאת tool calling והפרדת לוגיקה עסקית מהמודל.','דוגמה לימודית מוצעת, שלא הורצה כאן: סוכן Python מקבל נתוני מלאי סינתטיים ומחשב אילו מוצרים דורשים השלמה. הוא מחזיר JSON ל־ASP.NET Core לבדיקת סכימה וחוקים עסקיים; אין לו חיבור כתיבה למסד או הרשאה להזמין ציוד.','תכננו שני מימושים לאותו חישוב: כלי Python סגור ו־CodeAgent מבודד. פרטו אילו קבצים, פקודות וחיבורי רשת חסומים, ואיך בודקים שהתוצאה אינה מפעילה הזמנה.','הממשק הרשמי שנבדק הוא Python. לא נמצא SDK מקומי רשמי ל־TypeScript או C#/.NET. יישום .NET יכול לצרוך שירות Python שאתם מגדירים דרך HTTP; זו הצעת אינטגרציה ולא תמיכת .NET מקורית בספרייה.','OpenAI Agents SDK ללולאת כלים; Pydantic AI לחוזים מטיפוסים ב־Python; LangGraph כשנדרשים מצב וזרימה מפורשים. CodeAgent מוסיף אחריות על הרצת קוד, ולא רק בחירה של API.');
insert into academy.entry_sections (entry_id,position,title,body) values ('smolagents',0,'איזו בעיה היא פותרת?','smolagents מספקת לולאת סוכן קטנה: המודל מתכנן פעולה, כלי או קוד מבצעים אותה ותוצאת הפעולה חוזרת להמשך ההסקה. שימושים מרכזיים כוללים חיפוש, עיבוד נתונים והרכבת פעולות על מידע.');
insert into academy.entry_sections (entry_id,position,title,body) values ('smolagents',1,'איך בנויה ההרצה?','CodeAgent מתאר פעולות בקוד Python; ToolCallingAgent משתמש בקריאות כלים מובנות. יש להבחין בין מודל שמייצר טקסט לבין executor שמבצע פעולה. מבחינת מפתח C#, זהו גבול אמון כמו הפעלת קוד חיצוני, ולא פונקציית עזר רגילה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('smolagents',2,'שימושים מרכזיים','ניסוי בסוכן שמחשב תוצאות על נתונים או מאחזר מידע מכמה כלים. מודלים מקומיים ושירותי מודלים דורשים חיבור מתאים; עצם התמיכה במודל אינה מבטיחה איכות או תאימות מלאה לכל תרחיש.');
insert into academy.entry_sections (entry_id,position,title,body) values ('smolagents',3,'מתי לבחור ובמה להשוות?','השוואה פדגוגית: מול OpenAI Agents SDK השוו code actions לקריאות כלים; מול Pydantic AI השוו את חוזי הקלט והפלט והטיפוסים; מול LangGraph בדקו אם נדרש גרף עבודה מתמשך מעבר ללולאת הסוכן. התחילו מהפתרון הקטן שמספיק.');
insert into academy.entry_sections (entry_id,position,title,body) values ('smolagents',4,'גבולות ובטיחות','קוד שנוצר על ידי מודל עלול לקרוא קבצים או לבצע פעולות לא רצויות. בחרו בידוד executor מתאים, הגבילו רשת והרשאות ואל תספקו סודות לתרגיל. אין לראות בספרייה לבדה גבול אבטחה מלא למערכת ארגונית.');
