insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('smolagents','ספריית Python לסוכנים המפעילים כלים או קוד, ללימוד לולאת הסוכן וגבולות הריצה.','הממשק הרשמי שנבדק הוא Python. לא נמצא SDK מקומי רשמי ל־TypeScript או C#/.NET. יישום .NET יכול לצרוך שירות Python שאתם מגדירים דרך HTTP; זו הצעת אינטגרציה ולא תמיכת .NET מקורית בספרייה.','verified','המאגר הרשמי של הפרויקט; Stars הם צילום מצב ולא מדד איכות או מספר משתמשים.','2026-11-02T18:53:29.303Z');
