insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('agno','agno','Agno','framework','מסגרת Python לסוכנים, צוותים ותהליכי עבודה, עם כלים, זיכרון וידע. יש להבדיל בין ספריית הסוכנים לבין AgentOS, שכבת ההרצה והשירות שסביבה, ובין Agno לבין ההיסטוריה בשם Phidata.','published','verified','2026-11-02',1,'מקורות רשמיים נבדקו ב־2026-11-02; דוגמאות, תרגילים והשוואות מסומנים כפדגוגיים ולא הורצו. אין אימות מעבדתי לכל API.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User request 2026-11-02: add ADK, Mastra, smolagents, Agno and Legacy AutoGen; docs/DECISIONS.md D-029');
