insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('agno','היכרות עם REST/JSON, אימות קלט, לולאת tool calling והפרדת לוגיקה עסקית מהמודל.','דוגמה לימודית מוצעת, שלא הורצה כאן: סוכן Agno מאחזר נהלים ומידע לקוח לקריאה בלבד ומחזיר המלצת טיפול עם הפניות. שירות ASP.NET Core בודק הרשאות ומציג את ההמלצה לנציג, ורק פקודה נפרדת ומאושרת משנה רשומה ב־SQL.','הגדירו אילו נתוני לקוח מותר לשמור בזיכרון, ובנו חוזה JSON להמלצה עם מקורות. השוו סוכן יחיד ב־Agno לתכנון צוות ב־CrewAI, כולל התנהגות בכשל ואישור לפני כתיבה.','SDK הסוכנים הרשמי שנבדק נכתב ב־Python. AgentOS מציע API ו־MCP; אפשר לשלב יישום C#/.NET או TypeScript כלקוח של שירות, אך אין בכך הוכחה ל־SDK סוכנים מקומי באותן שפות.','CrewAI לצוותי תפקידים; Pydantic AI לחוזים מטיפוסים; LangGraph לזרימות מצב מפורשות. בחנו את עלות תחזוקת שירות Python מול Microsoft Agent Framework בסביבת .NET.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agno',0,'איזו בעיה היא פותרת?','Agno מאגדת בניית סוכן עם כלים, זיכרון וידע, ויכולה לשלב צוותים ו־Workflows. שימושים מרכזיים הם עוזרי ידע ועיבוד בקשות בארגון; סוכן יחיד הוא נקודת פתיחה סבירה לפני חלוקת העבודה לצוות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agno',1,'איך בנויה ההרצה?','מגדירים סוכן Python עם מודל וכלים, ובוחרים כיצד לשמור מצב וידע. AgentOS היא שכבת ההרצה והשירות שסביב הסוכנים. בהקבלה ל־.NET, ספריית הדומיין ושרת ה־API אינם אותו רכיב, גם אם שניהם מגיעים מאותו ספק.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agno',2,'שימושים מרכזיים','מענה לשאלות על מסמכים, איסוף נתונים עסקיים והצעת פעולה עם מקור. API ו־MCP מאפשרים חשיפת יכולות לצרכנים שונים; אחסון זיכרון דורש מדיניות פרטיות, הרשאות ותחזוקה משלכם.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agno',3,'מתי לבחור ובמה להשוות?','השוואה פדגוגית: מול CrewAI בחנו חלוקת אחריות בין סוכנים; מול Pydantic AI בדקו חוזים וטיפוסים; מול LangGraph בדקו כמה שליטה במצב ובענפים נחוצה. אין כאן אימוץ של טענות ביצועים שיווקיות או דירוג איכות לפי Stars.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agno',4,'גבולות ובטיחות','זיכרון ארוך טווח עשוי לשמור מידע רגיש. הגדירו גישה למידע ולכלים, תקופות שמירה ומחיקה, ותיעוד החלטות. שימוש בשכבת שירות אינו פוטר מאימות ב־API או מאישור אדם לפני שינוי עסקי.');
