insert into academy.entry_sources (entry_id,position,source_url,title,checked_at,supports) values ('agno',2,'https://github.com/agno-agi/agno/releases/tag/v1.0.0','Agno — השקת v1.0.0','2026-11-02','השקת Agno בצמוד לגרסה v1.0.0 ב־30 בינואר 2025 לפי Release רשמי. זו אינה טענה שזהו תחילת המאגר או הפרויקט הקודם Phidata; חבילות מוקדמות יותר קדמו לאירוע הזה.');
