insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('microsoft-autogen','microsoft-autogen','Microsoft AutoGen','framework','Legacy — מסגרת היסטורית של Microsoft למחקר ולבניית מערכות סוכנים מבוססות שיחות ואירועים. ה־README הרשמי מציין שהפרויקט הועבר לארכיון ואינו מתוחזק, ומפנה לפיתוח חדש ולתכנון מעבר אל Microsoft Agent Framework.','published','verified','2026-11-02',1,'מקורות רשמיים נבדקו ב־2026-11-02; דוגמאות, תרגילים והשוואות מסומנים כפדגוגיים ולא הורצו. אין אימות מעבדתי לכל API.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User request 2026-11-02: add ADK, Mastra, smolagents, Agno and Legacy AutoGen; docs/DECISIONS.md D-029');
insert into academy.entry_categories (entry_id,category_id,position) values ('microsoft-autogen','02',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('microsoft-autogen','היכרות עם REST/JSON, אימות קלט, לולאת tool calling והפרדת לוגיקה עסקית מהמודל.','תרחיש הגירה לימודי מוצע, שלא הורץ כאן: מערכת קיימת משתמשת ב־AutoGen להכנת המלצת רכש. תעדו את השיחות, הכלים והתוצרים, ואז בנו תרחיש שקול ב־Microsoft Agent Framework. השוו פלטים, הרשאות ואישור אדם לפני כל כתיבה ל־SQL; אל תריצו קוד לא מתוחזק מול נתוני ייצור לשם התרגיל.','הכינו טבלת מיפוי של Agent, כלי, מצב שיחה ותנאי עצירה מהמערכת הישנה למחליפה. בחרו שלוש בדיקות רגרסיה והסבירו אילו אינטגרציות C# מחייבות התאמה ידנית.','AutoGen כללה Python ו־.NET ברמת Core/runtime ותקשורת בין שפות. אין להסיק של־AgentChat ב־Python ולממשקי C# יש אותו כיסוי. מדובר בתמיכה היסטורית של פרויקט שאינו מתוחזק; לפיתוח חדש ב־C#/.NET יש לבחון Microsoft Agent Framework, ולא להתייחס ל־AutoGen כחלופה חדשה נתמכת.','Microsoft Agent Framework היא המחליפה שאליה מפנה Microsoft. CrewAI ו־LangGraph מספקות נקודות השוואה פדגוגיות לתזמור; הן אינן תחליף הגירה אוטומטי. AutoGen נשמרת כ־Legacy בלבד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-autogen',0,'מה היה תפקידה?','AutoGen חקרה פיתוח מערכות באמצעות שיחות בין סוכנים וכלים. שימושים היסטוריים כללו פתרון משימות קוד, ניתוח מידע ותיאום בין תפקידים. הרשומה נשמרת להבנת מערכות קיימות ולהגירה, ולא כהמלצה להתחיל מוצר חדש.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-autogen',1,'איך בנויה הארכיטקטורה ההיסטורית?','Core מספקת הודעות ו־runtime מונחה אירועים, ו־AgentChat מציעה API גבוה יותר לדפוסי שיחה. היו מימושי Python ו־.NET ברמת Core; יש לבדוק כל יכולת לפי הגרסה ולא להניח שממשקי השפות חופפים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-autogen',2,'Legacy ומצב התחזוקה','לפי ה־README הרשמי שנבדק, הפרויקט הועבר לארכיון ואינו מתוחזק על ידי Microsoft, לרבות תיקוני אבטחה ותמיכה. קיימים בדף גם ניסוחים ישנים על maintenance mode; הודעת הארכוב המפורשת היא הבסיס לסימון כאן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-autogen',3,'המעבר ל־Microsoft Agent Framework','מדריך Microsoft ממפה מודל, Agent, כלים, Session וזרימות עבודה לממשקי Agent Framework. המדריך שנבדק מתמקד ב־Python; הוא אינו ממיר אוטומטית קוד C#. הגירה דורשת מיפוי התנהגות, תלויות ושמירת מצב ובדיקות רגרסיה לפני החלפה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-autogen',4,'השוואה וסדר לימוד','השוואה פדגוגית: Microsoft Agent Framework היא היעד לבחינת פיתוח חדש במערכת Microsoft. השוו רעיונות שיחה ל־CrewAI ורעיונות מצב וזרימה ל־LangGraph. אין לייחס ל־AutoGen את התכונות או התמיכה העדכנית של המחליפה.');
