insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('microsoft-autogen','enrichment','העשרה היסטורית למי שנתקל בקוד AutoGen או מתכנן הגירה. לפיתוח חדש סדר הלימוד מתחיל ב־Microsoft Agent Framework; Stars של פרויקט ותיק אינם המלצה להתחיל בו.','2026-11-02','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('microsoft-autogen','מסגרת Legacy היסטורית לשיחות ותזמור סוכנים, עם מעבר מומלץ ל־Microsoft Agent Framework.','AutoGen כללה Python ו־.NET ברמת Core/runtime ותקשורת בין שפות. אין להסיק של־AgentChat ב־Python ולממשקי C# יש אותו כיסוי. מדובר בתמיכה היסטורית של פרויקט שאינו מתוחזק; לפיתוח חדש ב־C#/.NET יש לבחון Microsoft Agent Framework, ולא להתייחס ל־AutoGen כחלופה חדשה נתמכת.','verified','המאגר ההיסטורי הרשמי של Microsoft AutoGen; Stars מצטברים אינם מעידים על תחזוקה פעילה.','2026-11-02T18:53:30.483Z');
