-- Reviewed content addition; official sources and timestamped GitHub evidence only.
begin;
select pg_advisory_xact_lock(hashtext('academy-migrations'));
do $$ begin
 if (select max(version) from academy.schema_migrations) is distinct from 5 then raise exception 'Expected schema version 5'; end if;
 if exists(select 1 from academy.entries where slug in ('google-adk','mastra','smolagents','agno','microsoft-autogen') or lower(name) in ('google agent development kit (adk)','mastra','hugging face smolagents','agno','microsoft autogen')) then raise exception 'Requested framework already exists; review instead of overwriting'; end if;
 if exists(select 1 from academy.repositories where url in ('https://github.com/google/adk-python','https://github.com/mastra-ai/mastra','https://github.com/huggingface/smolagents','https://github.com/agno-agi/agno','https://github.com/microsoft/autogen')) then raise exception 'Repository already represented by another entry'; end if;
end $$;
create table academy.entry_lifecycle (
 entry_id text primary key references academy.entries(id),
 status text not null check(status='legacy'),
 note text not null check(length(trim(note))>0),
 successor_entry_id text not null references academy.entries(id),
 check(entry_id<>successor_entry_id)
);
alter table academy.entry_lifecycle enable row level security;
revoke all on academy.entry_lifecycle from public;
do $$ begin
 if (select count(*) from academy.entries where slug in ('google-adk','mastra','smolagents','agno','microsoft-autogen'))<>5 then raise exception 'Framework import incomplete'; end if;
 if (select count(*) from academy.entry_relations where entry_id in ('google-adk','mastra','smolagents','agno','microsoft-autogen'))<>16 then raise exception 'Related framework missing'; end if;
end $$;
commit;
